import {test,expect,request as apiRequest,type APIRequestContext,type Page,type TestInfo} from '@playwright/test';
import {randomUUID,createHash} from 'node:crypto';
import {writeFile} from 'node:fs/promises';
import {blankNotice,type NoticeContent} from '@/domain/notices/types';
import {blankContent,blankRequirement} from '@/domain/tasks/types';
import type {NoticeDetail} from '@/server/notices/contracts';
import type {TaskDetail} from '@/server/tasks/service';
import type {SubmissionWorkspace} from '@/server/submissions/contracts';
export const ctx='ctx-jp-a-luna';
export const origin=()=>`http://127.0.0.1:${process.env.E2E_PORT}`;
export async function post(r:APIRequestContext,url:string,body:unknown,status=200){const csrf=await(await r.get('/api/auth/csrf')).json();const response=await r.post(url,{data:body,headers:{Origin:origin(),'X-CSRF-Token':csrf.csrfToken}});expect(response.status(),`${url}: ${await response.text()}`).toBe(status);return response.json();}
export async function get<T>(r:APIRequestContext,url:string):Promise<T>{const response=await r.get(url);expect(response.status(),`${url}: ${await response.text()}`).toBe(200);return response.json();}
export async function api(email='admin@example.test'){const r=await apiRequest.newContext({baseURL:origin()});await post(r,'/api/auth/login',{email,password:'Demo-Hale-2026!'});return r;}
export async function login(page:Page,email='admin@example.test'){await page.context().clearCookies();await page.goto('/login');await page.getByRole('textbox',{name:'이메일',exact:true}).fill(email);await page.getByLabel('비밀번호',{exact:true}).fill('Demo-Hale-2026!');await page.getByRole('button',{name:'로그인',exact:true}).click();await expect(page).toHaveURL(/\/$/);}
export function tracing(){test.use({actionTimeout:12000});test.beforeEach(async({page})=>{await page.context().tracing.start({screenshots:true,snapshots:true,sources:true});});test.afterEach(async({page},info)=>{await writeFile(info.outputPath('final-dom-private.html'),await page.content());await page.screenshot({path:info.outputPath(info.status===info.expectedStatus?'final-private.png':'failure-private.png'),fullPage:true});await page.context().tracing.stop({path:info.outputPath('journey-private-trace.zip')});});}
export async function createNotice(r:APIRequestContext,content:Partial<NoticeContent>={},contextId=ctx){return(await post(r,'/api/notices',{contextId,content:{...blankNotice(),title:`합성 공지 ${randomUUID().slice(0,6)}`,body:'실제 공지 본문',...content},idempotencyKey:randomUUID()},201)).ids[0] as string;}
export async function detail(r:APIRequestContext,id:string){return get<NoticeDetail>(r,`/api/notices/${id}`);}
export async function noticeCommand(r:APIRequestContext,id:string,command:'save'|'publish',content?:NoticeContent){const d=await detail(r,id);return post(r,`/api/notices/${id}`,{command,expectedRevision:d.revision,...content?{content}:{},idempotencyKey:randomUUID()});}
export async function published(r:APIRequestContext,content:Partial<NoticeContent>={},contextId=ctx){const id=await createNotice(r,content,contextId);await noticeCommand(r,id,'publish');return id;}
export async function open(page:Page,id:string){await page.goto(`/notices/${id}?context=${ctx}`);await expect(page.getByRole('button',{name:'서버에서 새로 확인',exact:true})).toBeVisible();await expect(page.getByRole('status').filter({hasText:'정확한 공지 버전'})).toHaveCount(0);}
export function status(page:Page,text:string){return expect(page.locator('main').getByRole('status').filter({hasText:text})).toBeVisible();}
export const png=()=>Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a+ZkAAAAASUVORK5CYII=','base64');
export async function screenshot(page:Page,info:TestInfo,label:string){expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await page.screenshot({path:info.outputPath(label+'-full-private.png'),fullPage:true});if(info.project.name==='mobile'){await page.evaluate(()=>scrollTo(0,0));await page.screenshot({path:info.outputPath(label+'-390-viewport-private.png')});}}
export async function createTask(r:APIRequestContext,title:string,products:string[]=[]){const c=blankContent();c.title=title;c.description='실제 G04 요청 · 공지와 별도';c.deadline.responsibleUserId='user-gsg';c.requirements=[{...blankRequirement('answer'),label:'브랜드 답변'},{...blankRequirement('remaining','number'),label:'남은 수량'}];return(await post(r,'/api/tasks',{category:'spot',content:c,targets:[{contextId:ctx,ownerId:'user-gsg',assigneeId:'user-luna',coAssigneeIds:[],productIds:products}],idempotencyKey:randomUUID()},201)).ids[0] as string;}
export async function taskCommand(r:APIRequestContext,id:string,command:string){const d=await get<TaskDetail>(r,`/api/tasks/${id}`);return post(r,`/api/tasks/${id}`,{command,expectedRevision:d.task.revision,idempotencyKey:randomUUID()});}
export async function partial(r:APIRequestContext,id:string){await taskCommand(r,id,'accept');let w=await get<SubmissionWorkspace>(r,`/api/tasks/${id}/submissions`);const csrf=await(await r.get('/api/auth/csrf')).json();const uploaded=await r.post(`/api/files?taskId=${id}`,{headers:{Origin:origin(),'X-CSRF-Token':csrf.csrfToken},multipart:{files:{name:'partial-original.png',mimeType:'image/png',buffer:png()},visibility:'public'}});expect(uploaded.status()).toBe(201);const file=(await uploaded.json()).files[0];const answer=w.request.content.requirements.find(q=>q.type==='long_text')!;await post(r,`/api/tasks/${id}/submission-draft`,{command:'save',baseRequestId:w.request.id,expectedDraftRevision:0,idempotencyKey:randomUUID(),content:{answers:[{requestId:w.request.id,requirementKey:answer.key,productId:null,type:'long_text',input:{text:'실제 부분 제출 원문'}}],narrative:'합성 제출',artifacts:[{fileVersionId:file.id,role:'evidence',answer:null}],links:[],productSelections:w.products.map(p=>({productId:p.productId,expectedCommonRevision:p.commonRevision,expectedContextRevision:p.contextRevision,bindingIds:[],retailPriceVersionId:null,asOfDate:'2026-09-22'}))}});w=await get<SubmissionWorkspace>(r,`/api/tasks/${id}/submissions`);await post(r,`/api/tasks/${id}/submissions`,{baseRequestId:w.request.id,expectedDraftRevision:w.draft!.revision,expectedTaskRevision:w.taskRevision,mode:'partial',idempotencyKey:randomUUID()},201);const done=await get<SubmissionWorkspace>(r,`/api/tasks/${id}/submissions`);expect(done.taskStatus).toBe('partial');expect(done.latest!.mode).toBe('partial');expect(done.latest!.files).toHaveLength(1);return done;}
export const hash=(v:unknown)=>createHash('sha256').update(JSON.stringify(v)).digest('hex');
